package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object KenyaToolsCards {
    private val T = Track.KENYA_TOOLS
    val cards: List<Card> = listOf(
        // ---------- Level 1: Rookie ----------
        quiz("kt-mpesa-products", T, 1, "Which M-Pesa product is an overdraft that covers you when your balance runs short?",
            listOf("Fuliza", "M-Shwari Lock Savings", "Ziidi"), 0,
            "Fuliza lets a payment go through even if your balance is too low, then takes the money back from your next deposit, with fees. M-Shwari and KCB M-Pesa are save-and-borrow accounts; Ziidi is a fund.",
            source = "Safaricom, 2026"),
        concept("kt-chama", T, 1, "What's the difference between a merry-go-round chama and an investment chama?",
            "In a merry-go-round, everyone contributes and one member takes the whole pot each round. An investment chama pools money to buy assets (land, shares, T-bills) that the group owns together."),
        quiz("kt-kdic", T, 1, "If a Kenyan bank collapses, KDIC deposit insurance guarantees each depositor up to…",
            listOf("Ksh 50,000", "Ksh 500,000", "Everything they had"), 1,
            "KDIC covers up to Ksh 500,000 per depositor per member institution. In 2026 KDIC proposed raising it, but nothing above that is guaranteed until the change is gazetted (check kdic.go.ke).",
            source = "KDIC Act 2012; KDIC, 2026", timeSensitive = true),

        // ---------- Level 2: Hustler ----------
        quiz("kt-kdic-split", T, 2, "You have Ksh 900,000 split across two accounts at the same bank. If it fails, KDIC guarantees…",
            listOf("Ksh 900,000", "Ksh 500,000", "Ksh 1,000,000"), 1,
            "Accounts at one bank are added together into one claim, so only Ksh 500,000 is guaranteed. Spreading across different banks is what extends cover.",
            source = "KDIC, 2026", timeSensitive = true),
        concept("kt-kdic-excluded", T, 2, "What kinds of savings does KDIC deposit insurance NOT cover?",
            "MMFs, government securities and crypto aren't deposits, so KDIC doesn't cover them. MMF assets are held by a separate custodian, which is a different kind of protection.",
            source = "KDIC, 2026"),
        quiz("kt-sacco-shares", T, 2, "In a SACCO, how do share capital and deposits differ when you leave?",
            listOf("Both are refunded the same day", "Deposits are refunded after notice; shares are usually sold to another member", "Neither can ever be recovered"), 1,
            "Share capital is your ownership stake (earns dividends) and usually isn't refunded, only transferred. Deposits (earn interest, back your loans) are refunded after the notice period in the by-laws.",
            source = "SACCO by-laws (typical); SASRA"),
        quiz("kt-sacco-return", T, 2, "Ksh 20,000 in SACCO shares earns a 12% dividend, and Ksh 200,000 deposits earn 9% interest. Your gross return is…",
            listOf("Ksh 18,000", "Ksh 20,400", "Ksh 26,400"), 1,
            "Shares: 2,400. Deposits: 18,000. Total Ksh 20,400 before withholding tax. Most of the return usually comes from deposits.",
            source = "Basic maths"),
        concept("kt-mmf-monthly", T, 2, "Ksh 100,000 sits in an MMF yielding 10% a year. Roughly what does it earn in a month, after tax?",
            "About Ksh 833 gross (10% ÷ 12), and about Ksh 708 after 15% withholding tax. Interest is worked out daily and usually added monthly, so it compounds.",
            source = "KRA withholding rates, 2026", timeSensitive = true),
        quiz("kt-wht-interest", T, 2, "What withholding tax does a Kenyan resident pay on bank or MMF interest?",
            listOf("0%", "15%", "30%"), 1,
            "15%, taken at source, and it's a final tax for individuals, so you don't add it to your return. Compare funds on their net yield.",
            source = "KRA, 2026", timeSensitive = true),
        concept("kt-cma", T, 2, "Who approves and supervises money market funds and unit trusts in Kenya?",
            "The Capital Markets Authority. CMA approves collective investment schemes; by June 2026 there were 66 schemes with 320 funds. If it's not on CMA's list, don't send money.",
            source = "CMA CIS Report Q2 2026", tryThis = "Look up your fund on CMA's list of approved schemes."),
        concept("kt-merry-go-round", T, 2, "In a 10-person merry-go-round, who's really the borrower and who's the lender?",
            "Whoever takes the pot first gets an interest-free loan from the others; whoever goes last has lent interest-free for months. That's why groups often add a small top-up for late receivers."),
        quiz("kt-nssf-50k", T, 2, "You earn Ksh 50,000 a month in 2026. Your own NSSF deduction is…",
            listOf("Ksh 540", "Ksh 3,000", "Ksh 6,480"), 1,
            "6% of Ksh 50,000 = Ksh 3,000 (Ksh 540 Tier I + Ksh 2,460 Tier II). Your employer adds another Ksh 3,000.",
            source = "NSSF Act 2013, Year 4 rates (Feb 2026)", timeSensitive = true),
        quiz("kt-nssf-cap", T, 2, "You earn Ksh 200,000 a month. From February 2026, your NSSF deduction is…",
            listOf("Ksh 12,000", "Ksh 6,480", "Ksh 1,080"), 1,
            "Contributions stop at the upper earnings limit of Ksh 108,000: 6% of that is Ksh 6,480 from you and Ksh 6,480 from your employer.",
            source = "NSSF Year 4 rates (Feb 2026); KPMG", timeSensitive = true),
        quiz("kt-shif", T, 2, "SHIF takes 2.75% of gross pay, minimum Ksh 300. On a Ksh 40,000 salary that's…",
            listOf("Ksh 300", "Ksh 1,100", "Ksh 2,750"), 1,
            "2.75% × 40,000 = Ksh 1,100. There's no upper cap, and the employer doesn't match it.",
            source = "Social Health Insurance Act 2023; 2026", timeSensitive = true),
        concept("kt-housing-levy", T, 2, "How much is the Affordable Housing Levy on a payslip?",
            "1.5% of gross pay from you, matched by 1.5% from your employer. Since December 2024 your share is deducted before PAYE is calculated, which slightly lowers your income tax.",
            source = "Affordable Housing Act 2024; Tax Laws (Amendment) Act 2024", timeSensitive = true),

        you("kt-you-emergency", T, 2, "Your emergency target is {emergency_target} and you have {savings} saved. Where should the gap build up?",
            "Somewhere safe and quick to reach: an MMF such as Ziidi, or a bank savings account within the KDIC limit. Not shares, land or a 10-year bond.",
            tryThis = "Set up a small automatic transfer into your MMF after each payday.", signals = setOf(Signal.NO_EMERGENCY_FUND)),

        // ---------- Level 3: Pro ----------
        quiz("kt-tbill-min", T, 3, "On DhowCSD in 2026, the minimum non-competitive bid for a Treasury bill is…",
            listOf("Ksh 1,000", "Ksh 50,000", "Ksh 2 million"), 1,
            "CBK's 2026 auction notices set Ksh 50,000 (face value) for non-competitive bids and Ksh 2 million for competitive ones. You need an active CSD account (check each notice).",
            source = "CBK auction notices, 2026", timeSensitive = true),
        quiz("kt-tbill-discount", T, 3, "A Ksh 100,000 364-day T-bill at 10%: you pay about Ksh 92,300 (price plus tax upfront). Your net gain at maturity is about…",
            listOf("Ksh 10,000", "Ksh 7,700", "Ksh 8,500"), 1,
            "T-bills sell at a discount: about Ksh 90,900, plus ~Ksh 1,360 withholding tax deducted upfront. You get Ksh 100,000 back: about Ksh 7,700 net.",
            source = "CBK; KRA (15% WHT)", timeSensitive = true),
        quiz("kt-tbill-vs-mmf", T, 3, "A 364-day T-bill pays ~9% and your MMF ~8%, both taxed 15%. On Ksh 100,000 for a year, the T-bill earns about how much more?",
            listOf("About Ksh 850", "About Ksh 1,000", "About Ksh 8,500"), 0,
            "Net 7.65% vs 6.8%: about Ksh 850 more. The price is liquidity: an MMF pays out in days; a T-bill is locked till maturity unless sold.",
            source = "CBK results, Oct 2026", timeSensitive = true),
        quiz("kt-ifb", T, 3, "A tax-free infrastructure bond pays 12.7%. An ordinary bond taxed at 15% must pay about what to match it?",
            listOf("12.7%", "13.5%", "14.9%"), 2,
            "12.7 ÷ 0.85 ≈ 14.9%. Infrastructure bonds are exempt from withholding tax under the Income Tax Act; compare bonds on what you keep.",
            source = "CBK prospectuses; Business Daily, 2026", timeSensitive = true),
        quiz("kt-bond-wht", T, 3, "Withholding tax on government bond interest for residents is usually…",
            listOf("15%, or 10% for bonds of 10+ years; 0% on infrastructure bonds", "30% on all bonds", "0% on all bonds"), 0,
            "Longer bonds get a lower rate to encourage long-term saving, and infrastructure bonds are exempt. Check each prospectus.",
            source = "KRA, 2026", timeSensitive = true),
        quiz("kt-coupon", T, 3, "Ksh 100,000 in a bond with a 14% coupon, taxed at 15%. Each half-yearly payment reaches you as…",
            listOf("Ksh 14,000", "Ksh 7,000", "Ksh 5,950"), 2,
            "14% a year is Ksh 7,000 every six months; 15% WHT takes Ksh 1,050, leaving Ksh 5,950. The Ksh 100,000 comes back at maturity.",
            source = "Bond maths; KRA"),
        quiz("kt-two-csds", T, 3, "To buy both Safaricom shares and a Treasury bond, you need…",
            listOf("One M-Pesa account", "A CDS account via a broker, and a CBK CSD account on DhowCSD", "A KRA PIN only"), 1,
            "NSE shares sit in a CDSC account opened through a licensed stockbroker; government securities sit in CBK's CSD, opened free on DhowCSD. Both need your ID and KRA PIN.",
            source = "CBK; CDSC, 2026", tryThis = "Download the DhowCSD app and see what opening an account needs."),
        concept("kt-reit", T, 3, "What's the difference between an I-REIT and a D-REIT in Kenya?",
            "I-REITs own rent-earning property and must pay out at least 80% of profits; registered REITs are exempt from income tax. D-REITs build property instead.",
            source = "CMA REIT Regulations; Business Daily"),
        concept("kt-fahari", T, 3, "ILAM Fahari I-REIT listed in 2015 at Ksh 20 a unit. In early 2026 it traded around Ksh 11. What's the lesson?",
            "A listed property fund's price can fall below what the buildings seem worth, and stay there for years. Rent income isn't the same as capital safety, and thinly traded units can be hard to sell.",
            source = "NSE weekly summary, Feb 2026", timeSensitive = true),
        concept("kt-unit-trust", T, 3, "Besides MMFs, what other kinds of unit trust can you buy in Kenya?",
            "Fixed-income (bond) funds, equity funds, balanced funds and \"special\" funds. Higher potential return comes with prices that can fall; only MMFs aim to keep a steady Ksh 1 value.",
            source = "CMA CIS Report Q2 2026"),
        concept("kt-rollover", T, 3, "Your T-bill matures and you roll it over. What risk are you taking?",
            "Reinvestment risk: if rates have fallen, the new bill pays less. Locking some money in longer bonds sets the rate for years, but their prices move if rates change before maturity."),
        concept("kt-sell-bond", T, 3, "Can you get your money out of a Treasury bond before it matures?",
            "Yes: sell it on the secondary market through DhowCSD or a broker on the NSE. You get the market price, which is below what you paid if rates have risen since you bought.",
            source = "CBK DhowCSD, 2023"),

        // ---------- Level 4: Shark ----------
        quiz("kt-paye-bands", T, 4, "Kenya's monthly PAYE bands in 2026 start at 10% up to Ksh 24,000. The top rate is…",
            listOf("30%, above Ksh 32,333", "35%, above Ksh 800,000", "40%, above Ksh 1 million"), 1,
            "Bands: 10% to 24,000; 25% to 32,333; 30% to 500,000; 32.5% to 800,000; 35% above. Personal relief of Ksh 2,400 a month is then subtracted. 2026 relief proposals were dropped.",
            source = "Income Tax Act; Finance Act 2023; KRA, 2026", timeSensitive = true),
        quiz("kt-paye-calc", T, 4, "Your taxable pay is Ksh 50,000 a month. After personal relief, PAYE is about…",
            listOf("Ksh 5,000", "Ksh 7,400", "Ksh 12,500"), 1,
            "2,400 (first 24,000 at 10%) + 2,083 (next 8,333 at 25%) + 5,300 (last 17,667 at 30%) = 9,783, minus 2,400 relief = about Ksh 7,383.",
            source = "KRA PAYE bands, 2026", timeSensitive = true),
        concept("kt-taxable-pay", T, 4, "Why is your \"taxable pay\" lower than your gross salary?",
            "NSSF, SHIF, your housing levy share and registered pension contributions are deducted before PAYE is worked out (SHIF and the levy since the Tax Laws (Amendment) Act 2024).",
            source = "Tax Laws (Amendment) Act 2024", timeSensitive = true, tryThis = "Check the taxable pay line on your last payslip."),
        quiz("kt-payslip", T, 4, "Gross Ksh 100,000: NSSF 6,000, SHIF 2,750, housing levy 1,500, then PAYE on Ksh 89,750. Take-home is about…",
            listOf("Ksh 70,400", "Ksh 76,000", "Ksh 81,000"), 0,
            "PAYE on 89,750 is 21,708 minus 2,400 relief = 19,308. 100,000 − 6,000 − 2,750 − 1,500 − 19,308 ≈ Ksh 70,440, before any loans or SACCO check-offs.",
            source = "KRA; NSSF; SHA rates, 2026", timeSensitive = true),
        quiz("kt-pension-limit", T, 4, "How much can you put into registered pension schemes each month and deduct from taxable pay?",
            listOf("Ksh 20,000", "Ksh 30,000", "Unlimited"), 1,
            "The Tax Laws (Amendment) Act 2024 raised it from Ksh 20,000 to Ksh 30,000 a month (Ksh 360,000 a year), from 27 December 2024.",
            source = "Tax Laws (Amendment) Act 2024; RBA", timeSensitive = true),
        quiz("kt-pension-saving", T, 4, "You're in the 30% band and add Ksh 10,000 a month to a pension plan. Your PAYE falls by about…",
            listOf("Ksh 1,000", "Ksh 3,000", "Ksh 10,000"), 1,
            "The Ksh 10,000 leaves taxable pay, saving 30% of it: Ksh 3,000 a month. So Ksh 10,000 of saving costs you only Ksh 7,000 of take-home.",
            source = "Basic maths; KRA", tryThis = "Compare your pension contribution with the Ksh 30,000 limit.", timeSensitive = true),
        concept("kt-ipp", T, 4, "What is an Individual Pension Plan (IPP), and who is it for?",
            "A personal retirement scheme registered with the RBA, run by an insurer or fund manager. It suits self-employed people and anyone topping up: you choose contributions and get the same pension tax deduction.",
            source = "Retirement Benefits Authority"),
        quiz("kt-pension-exempt", T, 4, "After the Finance Act 2025, pension benefits are tax-free if you…",
            listOf("Withdraw at any age", "Retire at scheme age, after 20 years' membership, or on ill health", "Never; all pension payouts are taxed"), 1,
            "The Act replaced the old tax-free lump sums (like the Ksh 600,000) with full exemption in these cases. Early withdrawals are still taxed, so check before you cash out.",
            source = "Finance Act 2025; Grant Thornton", timeSensitive = true),
        quiz("kt-mortgage-interest", T, 4, "How much mortgage interest a year can an employee deduct from taxable income?",
            listOf("Ksh 36,000", "Ksh 360,000", "All of it"), 1,
            "Up to Ksh 360,000 a year (Ksh 30,000 a month) on loans from qualifying lenders. Since the Finance Act 2025 it also covers loans to build your home.",
            source = "KRA, 2026; Finance Act 2025", timeSensitive = true),
        concept("kt-insurance-relief", T, 4, "How does insurance relief cut your PAYE?",
            "You get back 15% of qualifying life, health or education premiums, up to Ksh 5,000 a month (Ksh 60,000 a year), taken off your PAYE. Paying Ksh 10,000 in premiums gives Ksh 1,500 relief.",
            source = "Income Tax Act; KRA, 2026", timeSensitive = true),
        quiz("kt-regulators", T, 4, "Match the regulator: who supervises insurers, and who supervises pension schemes?",
            listOf("IRA insures; RBA pensions", "CMA insures; SASRA pensions", "CBK both"), 0,
            "IRA (insurers), RBA (pensions), CMA (NSE, MMFs, unit trusts, REITs), CBK (banks, microfinance, digital lenders) and SASRA (deposit-taking SACCOs).",
            source = "Kenyan statutes"),
        quiz("kt-regulator-complaint", T, 4, "A loan app keeps harassing you and isn't on any official list. Which regulator do you check first?",
            listOf("CMA", "CBK", "IRA"), 1,
            "CBK licenses digital credit providers and publishes the list; unlicensed lending is illegal. For data misuse you can also complain to the Data Protection Commissioner.",
            source = "CBK, 2026", signals = setOf(Signal.HAS_DEBT)),

        // ---------- Level 5: Legend ----------
        quiz("kt-suri-jack", T, 5, "Suri & Jack (Science, 2016) estimated that access to M-Pesa lifted how many Kenyan households out of extreme poverty?",
            listOf("About 19,000", "About 194,000 (2%)", "About 1.9 million"), 1,
            "About 194,000 households, or 2%. The effect was bigger for female-headed households.",
            source = "Suri & Jack, 2016 (Science)"),
        concept("kt-suri-why", T, 5, "According to Suri & Jack, how did M-Pesa reduce poverty?",
            "Mostly through better money habits, not by moving people: households saved more and coped better with shocks, and many women moved from farming into business or retail.",
            source = "Suri & Jack, 2016 (Science)"),
        quiz("kt-makiba", T, 5, "M-Akiba (2017) was a world first. What was it?",
            listOf("A government bond sold by phone, from Ksh 3,000", "Kenya's first ATM", "A crypto coin"), 0,
            "A 3-year, 10%, tax-free retail infrastructure bond bought via *889#, with no bank account needed.",
            source = "National Treasury; Reuters, 2017"),
        quiz("kt-imperial", T, 5, "Imperial Bank was put under receivership in October 2015 because of…",
            listOf("A cyber attack", "Insider fraud of tens of billions of shillings", "A currency crash"), 1,
            "Directors reported a long-running scheme in which over Ksh 34 billion was allegedly moved to favoured clients over 13 years. Depositors above the insured limit waited years for partial refunds.",
            source = "CBK; Business Daily; Nation"),
        quiz("kt-chase", T, 5, "What triggered Chase Bank's collapse in April 2016?",
            listOf("A run on deposits sparked by online reports", "A drought", "A KRA tax demand"), 0,
            "Chase went into receivership on 7 April 2016, reopened on 27 April under KCB management, and SBM Bank took over most of it in 2018. Confidence can sink a bank in days.",
            source = "CBK; KDIC; Business Daily, 2018"),
        concept("kt-bank-lesson", T, 5, "Dubai Bank, Imperial Bank and Chase Bank all failed in 2015–16. What should a saver take from that?",
            "Keep each bank's balance within the KDIC limit, spread large sums, and don't chase the highest deposit rate: weak banks often pay most to attract money.",
            source = "CBK; KDIC"),
        quiz("kt-dhowcsd", T, 5, "DhowCSD (live from July 2023) replaced which old way of buying government securities?",
            listOf("Manual paper bids lodged at CBK or banks", "Buying via M-Pesa agents", "Lottery draws"), 0,
            "Bids, payments, portfolio statements, secondary trading and pledging moved to one CBK app, open to Kenyans abroad too. Paper and cash bids ended.",
            source = "CBK, 2023"),
        concept("kt-auction", T, 5, "How does CBK decide the rate in a T-bill auction?",
            "Competitive bids name a rate; CBK ranks them, accepts from the lowest until it has enough, and sets a cut-off. Bids above the cut-off are rejected. Non-competitive bids get the average accepted rate.",
            source = "CBK auction notices, 2026"),
        quiz("kt-competitive-risk", T, 5, "You place a competitive T-bill bid at 9.5% and the cut-off comes in at 9.2%. What happens?",
            listOf("You get 9.5%", "You get 9.2%", "Your bid is rejected"), 2,
            "Bids priced above the cut-off rate miss out. That's why most individuals bid non-competitively (capped at Ksh 50 million per tenor) and simply take the average.",
            source = "CBK auction notices, 2026", timeSensitive = true),
        concept("kt-chama-legal", T, 5, "How do most Kenyan chamas become legal entities?",
            "Most register as self-help groups with the State Department for Social Protection. Registration lets the group open accounts and own assets in its name. Larger investment groups often form a company or cooperative instead, for clearer ownership and limited liability.",
            source = "State Dept for Social Protection; Nation"),
        concept("kt-chama-company", T, 5, "Why might a chama that's buying land switch from a self-help group to a company?",
            "A company has shares, limited liability and a clear way for members to exit or pass on their stake. In a self-help group, members can be jointly liable for group debts and ownership is harder to prove.",
            source = "Companies Act 2015; Nation"),
        quiz("kt-cis-shift", T, 5, "MMFs were about 90% of Kenya's unit trust assets in 2020. By June 2026 their share was about…",
            listOf("95%", "48%", "10%"), 1,
            "About 48% of Ksh 948.7 billion, as special and fixed-income funds grew faster. More Kenyans now hold riskier funds, so read each fund's factsheet.",
            source = "CMA CIS Report Q2 2026", timeSensitive = true),
    )
}
